// Demo: Force-Directed Layouts — force layout iterations
var n=3,energy=100;
console.log('technique: Force-Directed Layouts');
for(var i=0;i<5;i++){energy*=0.6;console.log('iteration '+(i+1)+': energy '+energy.toFixed(1));}
