// Demo: Module Constellations — cycle detection in 15 modules
var edges=[];for(var i=0;i<15;i++){edges.push([i,(i*7+3)%15]);}
var cyclic=edges.filter(function(e){return e[0]===e[1]||edges.some(function(f){return f[0]===e[1]&&f[1]===e[0];});});
console.log('technique: Module Constellations');console.log('edges: '+edges.length+', cyclic pairs: '+cyclic.length/2);
console.log(cyclic.length?'cycles glow red — break them':'acyclic — clean layers');

