// Demo: Impact Analysis — impact radius of a change
var deps={};for(var i=0;i<30;i++){deps['m'+i]=['m'+((i*13+5)%30)];}
var start='m0',seen={},q=[start];
while(q.length){var m=q.pop();if(seen[m])continue;seen[m]=1;(deps[m]||[]).forEach(function(d){q.push(d);});}
console.log('technique: Impact Analysis');console.log('changing '+start+' affects '+Object.keys(seen).length+' of '+30+' modules');

